// Keep the select as the single source of truth for form/API integrations.
export function glassWheelPicker(select,label){
 const wrap=document.createElement('div');wrap.className='music-wheel-picker';
 const title=document.createElement('span');title.className='music-wheel-label';title.textContent=label;
 const trigger=document.createElement('button');trigger.type='button';trigger.className='music-wheel-trigger';trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label',label);
 const value=document.createElement('span'),chevron=document.createElement('span');chevron.textContent='⌃⌄';chevron.setAttribute('aria-hidden','true');trigger.append(value,chevron);
 const surface=document.createElement('div');surface.className='music-wheel-surface';surface.hidden=true;
 const rail=document.createElement('div');rail.className='music-wheel-rail';rail.setAttribute('role','listbox');rail.setAttribute('aria-label',label);surface.append(rail);wrap.append(title,trigger,surface,select);select.hidden=true;
 let choices=[],timer=0,positioning=false,userScroll=false;
 const reduced=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;
 function sync(){value.textContent=select.selectedOptions[0]?.textContent||'—';for(const row of choices)row.setAttribute('aria-selected',String(row.dataset.value===select.value));}
 function close(){clearTimeout(timer);trigger.setAttribute('aria-expanded','false');wrap.classList.remove('is-open');surface.hidden=true;}
 function commit(row){if(!row)return;select.value=row.dataset.value;select.dispatchEvent(new Event('change',{bubbles:true}));sync();}
 function center(row,smooth=false){if(!row)return;rail.scrollTo({top:row.offsetTop-rail.offsetTop-(rail.clientHeight-row.offsetHeight)/2,behavior:smooth&&!reduced()?'smooth':'instant'});}
 function appearance(){const mid=rail.scrollTop+rail.clientHeight/2;for(const row of choices){const distance=(row.offsetTop-rail.offsetTop+row.offsetHeight/2-mid)/42;row.style.setProperty('--wheel-distance',String(Math.max(-3,Math.min(3,distance))));row.style.opacity=String(Math.max(.25,1-Math.abs(distance)*.22));row.style.filter=`blur(${Math.min(1.2,Math.abs(distance)*.3)}px)`;row.classList.toggle('is-centered',Math.abs(distance)<.55);}}
 function rebuild(){choices=[];rail.replaceChildren();for(const option of select.options){const row=document.createElement('button');row.type='button';row.className='music-wheel-choice';row.dataset.value=option.value;row.textContent=option.textContent;row.disabled=option.disabled;row.setAttribute('role','option');const group=option.parentElement.tagName==='OPTGROUP'?option.parentElement.label:'';if(group)row.setAttribute('aria-label',group+'：'+option.textContent);row.onclick=()=>{commit(row);close();trigger.focus({preventScroll:true});};rail.append(row);choices.push(row);}sync();if(!surface.hidden){positioning=true;center(choices.find(r=>r.dataset.value===select.value));appearance();requestAnimationFrame(()=>positioning=false);}}
 trigger.onclick=()=>{if(!surface.hidden){close();return;}document.dispatchEvent(new CustomEvent('music-wheel-open',{detail:wrap}));surface.hidden=false;wrap.classList.add('is-open');trigger.setAttribute('aria-expanded','true');positioning=true;userScroll=false;center(choices.find(r=>r.dataset.value===select.value));appearance();requestAnimationFrame(()=>positioning=false);};
 rail.addEventListener('pointerdown',()=>{userScroll=true;positioning=false;});rail.addEventListener('wheel',()=>{userScroll=true;positioning=false;},{passive:true});
 rail.addEventListener('scroll',()=>{appearance();clearTimeout(timer);if(positioning||!userScroll)return;timer=setTimeout(()=>{const mid=rail.scrollTop+rail.clientHeight/2;const nearest=choices.filter(r=>!r.disabled).reduce((a,b)=>!a?b:Math.abs(a.offsetTop-rail.offsetTop+a.offsetHeight/2-mid)<Math.abs(b.offsetTop-rail.offsetTop+b.offsetHeight/2-mid)?a:b,null);commit(nearest);},150);},{passive:true});
 rail.addEventListener('keydown',event=>{if(!['ArrowDown','ArrowUp','Home','End','Escape'].includes(event.key))return;event.preventDefault();if(event.key==='Escape'){close();trigger.focus();return;}let i=choices.findIndex(r=>r.dataset.value===select.value);i=event.key==='Home'?0:event.key==='End'?choices.length-1:Math.max(0,Math.min(choices.length-1,i+(event.key==='ArrowDown'?1:-1)));commit(choices[i]);center(choices[i],true);});rail.tabIndex=0;
 document.addEventListener('music-wheel-open',event=>{if(event.detail!==wrap)close();});wrap.addEventListener('focusout',event=>{if(!wrap.contains(event.relatedTarget))close();});select.addEventListener('change',sync);new MutationObserver(rebuild).observe(select,{childList:true,subtree:true,characterData:true});rebuild();return wrap;
}
